function syncDataFiles(dbname,baseurl){var retval={};if(typeof dbname==="undefined"){dbname="ut99_exs";}
if(typeof baseurl==="undefined"){baseurl="/games/ut99/gamedata/";}
var urlrandomizerarg="?nocache="+(Date.now()/1000|0);var state={db:null,reported_result:false,xhrs:{},remote_manifest:{},remote_manifest_loaded:false,local_manifest:{},local_manifest_loaded:false,total_to_download:0,total_downloaded:0,total_files:0,pending_files:0};var log=function(str){console.log("CACHEAPPDATA: "+str);};var debug=function(str){};var clear_state=function(){for(var i in state.xhrs){state.xhrs[i].abort();}
delete state.db;delete state.xhrs;delete state.remote_manifest;delete state.local_manifest;};var failed=function(why){if(state.reported_result){return;}
state.reported_result=true;log("[FAILURE] "+why);clear_state();if(retval.onerror){retval.onerror(why);}};var progress=function(str,percent,loaded,total){if(state.reported_result){return;}
debug("[PROGRESS] "+str);if(retval.onprogress){retval.onprogress(percent||0,loaded||0,total||0,str);}};var succeeded=function(){if(state.reported_result){return;}
state.reported_result=true;log("[SUCCESS] Files are synchronized and ready.");clear_state();if(retval.onfinish){retval.onfinish();}};var populate_emscripten_fs=function(){if(state.reported_result){return;}
debug("Populating Emscripten filesystem from IndexedDB...");if(typeof FS==="undefined"){debug("FS is undefined, skipping local filesystem mount.");succeeded();return;}
var transaction=state.db.transaction(["metadata","data"],"readonly");var metadata_store=transaction.objectStore("metadata");var data_store=transaction.objectStore("data");var data_index=data_store.index("data");var cursor_req=metadata_store.openCursor();cursor_req.onsuccess=function(e){var cursor=e.target.result;if(cursor){var item=cursor.value;var parts=item.filename.split('/');var currentDir='';for(var p=0;p<parts.length-1;p++){currentDir+=(p===0?'':'/')+parts[p];try{FS.mkdir(currentDir);}catch(err){}}
var chunk_cursor_req=data_index.openCursor(IDBKeyRange.only(item.filename));var fileBuffer=new Uint8Array(item.filesize);chunk_cursor_req.onsuccess=function(ce){var chunk_cursor=ce.target.result;if(chunk_cursor){var chunk=chunk_cursor.value;var chunkData=new Uint8Array(chunk.data);fileBuffer.set(chunkData,chunk.offset);chunk_cursor.continue();}else{try{FS.writeFile(item.filename,fileBuffer);debug("Mounted "+item.filename+" ("+item.filesize+" bytes)");}catch(err){console.warn("Failed to write "+item.filename,err);}}};cursor.continue();}else{succeeded();}};cursor_req.onerror=function(){succeeded();};};var store_file=function(xhr){if(state.reported_result){return;}
var transaction=state.db.transaction(["metadata","data"],"readwrite");transaction.oncomplete=function(event){debug("IndexedDB transaction committed for "+xhr.filename);state.pending_files--;if(state.pending_files===0){populate_emscripten_fs();}};transaction.onerror=function(event){failed("Failed to save "+xhr.filename+" to IndexedDB: "+event.target.error.message);};var metadata=transaction.objectStore("metadata");var data=transaction.objectStore("data");metadata.put({filename:xhr.filename,filesize:xhr.filesize,filetime:xhr.filetime});var chunk_size=524288;var total_chunks=Math.ceil(xhr.response.byteLength/chunk_size);for(var c=0;c<total_chunks;c++){var start=c*chunk_size;var end=Math.min(start+chunk_size,xhr.response.byteLength);var chunk_data=xhr.response.slice(start,end);data.put({filename:xhr.filename,chunkid:xhr.filename+"_"+c,offset:start,size:end-start,data:chunk_data});}};var download_new_files=function(){if(state.reported_result){return;}
state.pending_files=0;state.total_to_download=0;state.total_downloaded=0;var files_to_download=[];for(var fname in state.remote_manifest){var remote=state.remote_manifest[fname];var local=state.local_manifest[fname];if(!local||local.filesize!==remote.filesize||local.filetime!==remote.filetime){files_to_download.push(fname);state.total_to_download+=remote.filesize;}}
if(files_to_download.length===0){debug("All files up to date in cache.");populate_emscripten_fs();return;}
state.pending_files=files_to_download.length;progress("Lejuplādē spēles pakotnes...",0,0,state.total_to_download);for(var f=0;f<files_to_download.length;f++){(function(filename){var remoteitem=state.remote_manifest[filename];var xhr=new XMLHttpRequest();xhr.filename=filename;xhr.filesize=remoteitem.filesize;xhr.filetime=remoteitem.filetime;xhr.previously_loaded=0;xhr.responseType="arraybuffer";xhr.addEventListener("progress",function(e){var diff=e.loaded-xhr.previously_loaded;state.total_downloaded+=diff;xhr.previously_loaded=e.loaded;var pct=Math.min(100,Math.floor((state.total_downloaded/state.total_to_download)*100));progress("Lejuplādē "+filename+"...",pct,state.total_downloaded,state.total_to_download);});xhr.addEventListener("load",function(){if(xhr.status===200){store_file(xhr);}else{console.warn("Could not load asset: "+filename);state.pending_files--;if(state.pending_files===0){populate_emscripten_fs();}}});xhr.addEventListener("error",function(){console.warn("XHR error on "+filename);state.pending_files--;if(state.pending_files===0){populate_emscripten_fs();}});xhr.open("GET",baseurl+filename+urlrandomizerarg,true);xhr.send();})(files_to_download[f]);}};var load_local_manifest=function(db){var tx=db.transaction("metadata","readonly");var store=tx.objectStore("metadata");var cursorReq=store.openCursor();cursorReq.onsuccess=function(e){var cursor=e.target.result;if(cursor){state.local_manifest[cursor.value.filename]=cursor.value;cursor.continue();}else{state.local_manifest_loaded=true;if(state.remote_manifest_loaded){download_new_files();}}};cursorReq.onerror=function(){state.local_manifest_loaded=true;if(state.remote_manifest_loaded){download_new_files();}};};try{var req=indexedDB.open(dbname,1);req.onupgradeneeded=function(e){var db=e.target.result;if(!db.objectStoreNames.contains("metadata")){db.createObjectStore("metadata",{keyPath:"filename"});}
if(!db.objectStoreNames.contains("data")){var dataStore=db.createObjectStore("data",{keyPath:"chunkid"});dataStore.createIndex("data","filename",{unique:false});}};req.onsuccess=function(e){state.db=e.target.result;load_local_manifest(state.db);var xhr=new XMLHttpRequest();xhr.responseType="text";xhr.addEventListener("load",function(){if(xhr.status===200){try{state.remote_manifest=JSON.parse(xhr.responseText);state.remote_manifest_loaded=true;if(state.local_manifest_loaded){download_new_files();}}catch(err){failed("Neizdevās apstrādāt manifest.json");}}else{console.warn("Remote manifest returned status "+xhr.status);succeeded();}});xhr.addEventListener("error",function(){succeeded();});xhr.open("GET",baseurl+"manifest.json"+urlrandomizerarg,true);xhr.send();};req.onerror=function(){succeeded();};}catch(e){succeeded();}
return retval;}
window.syncDataFiles=syncDataFiles;